      "zh": "呢間餐廳啲嘢食好正，不過價錢有啲貴。如果你想平啲，隔籬有間茶餐廳。",
      "en": "The food at this restaurant is great, but a bit expensive. If you want something cheaper, there is a cafe next door.",
      "cat": "飲食",
      "jyutping": "ni1 gaan1 caan1 teng1 di1 je5 sik6 hou2 zeng3 bat1 gwo3 gaa3 cin4 jau5 di1 gwai3 jyu4 gwo2 nei5 soeng2 peng4 di1 gaak3 lei4 jau5 gaan1 caa4 caan1 teng1",
